      SUBROUTINE RDSTEPCC---- DETERMINE IDENTITY, RANGE, AND STEP SIZE FOR STEPPED PARAMETERC      INCLUDE 'TRNSPRT_PARAM.CIN'      INCLUDE 'IODATA.CIN'      INCLUDE 'IOFLAG.CIN'      INCLUDE 'NPLIN.CIN'      INCLUDE 'PARDAT.CIN'      INCLUDE 'PARVAL.CIN'      INCLUDE 'RDBUFF.CIN'      INCLUDE 'RDCHAR.CIN'      INCLUDE 'STEPTC.CIN'      INCLUDE 'STEPT1.CIN'C-----------------------------------------------------------------------      CHARACTER*15    KNAME, KPARA      CHARACTER*15    DSTEP(3)      INTEGER         TEXT      EXTERNAL        IDATA      DATA            DSTEP /'LOWER','UPPER','STEP'/      DATA            NCSTEP /3/, NSTEP /3/CC---- COMMA?C      CALL RDNEXT      IF (ENDFIL) GO TO 800      IF (ITEM .EQ. COMMA) THEN        CALL RDNEXT        IF (ENDFIL) GO TO 800      ENDIFCC---- PARAMETER KEYWORDC      CALL RDWORD(KNAME,LNAME)      IF (KNAME .NE. 'NAME') GO TO 40      CALL RDNEXT      IF (ENDFIL) GO TO 800      IF (ITEM .NE. EQUAL) THEN        CALL RDFAIL        WRITE (IECHO,905)        GO TO 800      ENDIFCC---- PARAMETER NAMEC      CALL RDNEXT      IF (ENDFIL) GO TO 800      CALL RDWORD(KNAME,LNAME)      IF (LNAME .EQ. 0) THEN        CALL RDFAIL        WRITE (IECHO,910)        GO TO 800      ENDIF   40 STCTYP = KNAMEC   50 IPARM = 0      CALL RDNEXT      IF (ENDFIL) GO TO 800      IF (ITEM .EQ. '[') THEN        CALL RDNEXT        IF (ENDFIL) GO TO 800        CALL RDWORD(KPARA,LPARA)        IF (LPARA .EQ. 0) THEN                  CALL RDFAIL          WRITE (IECHO,930)          GO TO 800        ENDIF        STCPAR = KPARA        CALL RDNEXT        IF (ENDFIL) GO TO 800        CALL RDTEST(']',ERROR)C        IF (ERROR) GO TO 800        IF (TEXT(1) .LT. 0) GO TO 600      ELSE        CALL RDBACK      ENDIFC      CALL DECPAR(NSTEP,DSTEP,NCSTEP,NPLIN,NSTEP)      IF (ENDFIL) GO TO 600      STLO = PDATA(1)      STHI = PDATA(2)      STEP = PDATA(3)      LSTEP = .TRUE.      NSTEPS = IFIX((STHI - STLO)/STEP + 1.001)C  600 CONTINUE      GO TO 900CC---- ERROR EXITC  800 ERROR = .TRUE.  900 RETURNC-----------------------------------------------------------------------  905 FORMAT (' *** ERROR *** EQUAL EXPECTED'/' ')  910 FORMAT (' *** ERROR *** PARAMETER NAME EXPECTED'/' ')  930 FORMAT (' *** ERROR *** PARAMETER KEYWORD EXPECTED'/' ')C-----------------------------------------------------------------------      END